/* One presentation of two existing ownership models. Manual notes never enter Catalog V2. */
window.ND_INVENTORY=(()=>{
 const V=()=>window.ND_CATALOG_V2,S=()=>window.ND_SHEET_V2;
 const groups=[['all','Все предметы','inventory'],['weapon','Оружие','weapons'],['armor','Броня и одежда','armor'],['implant','Импланты','chrome'],['network','Нейродеки','network'],['medicine','Медикаменты','health'],['stimulant','Стимуляторы','health'],['gadget','Гаджеты','inventory'],['other','Прочее','inventory']];
 const labels={inventory:'В инвентаре',equipped:'Экипировано',installed:'Установлено',loaded:'Загружено',learned:'Изучено',consumed:'Израсходовано'};
 const uiStates=new Map();
 const state=()=>{const key=cloudRecord?.id||'local';if(!uiStates.has(key))uiStates.set(key,{query:'',category:'all',source:'all',active:false,sort:'default',selected:null});return uiStates.get(key);};
 const icon=id=>window.ND_DOSSIER.uiIcon(id);
 const name=i=>i.displayName||i.name||'Неизвестный предмет';
 const className=i=>V().classes.find(c=>c.id===i.classId)?.label||'Без классификации';
 const group=i=>({ranged_weapon:'weapon',melee_weapon:'weapon',throwable:'weapon',clothing_armor:'armor',implant:'implant',neurodeck:'network',worm:'network',heavy_demon:'network',medicine:'medicine',stimulant:'stimulant',gadget:'gadget'}[i.classId]||'other');
 const active=x=>x.quantity>0&&['equipped','installed','loaded','learned'].includes(x.location)&&x.equipped!==false;
 function entries(c=card,catalog=D.catalog){const linked=V().normalizeCharacter(c,catalog).equipmentItems.map(x=>{const item=V().resolve(catalog,x.catalogId)||x.snapshot||{};return {id:x.instanceId,source:'catalog',name:name(item),description:item.description||'',manufacturer:item.manufacturer||'',category:group(item),quantity:x.quantity,price:item.classId==='perk'?null:item.economy?.price,active:active(x),location:x.location,item,instance:x};}).filter(x=>!['worm','heavy_demon'].includes(x.item.classId));return linked.concat(c.inventory.map((x,index)=>({id:'manual:'+index,index,source:'manual',name:x.name,description:x.description,manufacturer:'',category:'other',quantity:x.quantity??1,price:null,active:false,location:'inventory',item:x})));}
 function query(rows,filter){const q=filter.query.trim().toLocaleLowerCase('ru');const found=rows.filter(x=>(filter.category==='all'||x.category===filter.category)&&(filter.source==='all'||x.source===filter.source)&&(!filter.active||x.active)&&(!q||(x.name+' '+x.description+' '+x.manufacturer).toLocaleLowerCase('ru').includes(q)));const collator=new Intl.Collator('ru',{numeric:true,sensitivity:'base'});const cmp={alphabet:(a,b)=>collator.compare(a.name,b.name),category:(a,b)=>groups.findIndex(g=>g[0]===a.category)-groups.findIndex(g=>g[0]===b.category)||collator.compare(a.name,b.name),quantity:(a,b)=>b.quantity-a.quantity,price:(a,b)=>(a.price==null)-(b.price==null)||(a.price??0)-(b.price??0),equipped:(a,b)=>Number(b.active)-Number(a.active)}[filter.sort];return cmp?found.sort(cmp):found;}
 function art(x,large=false){const image=typeof catalogIcon==='function'?catalogIcon(x.item,'inventory-image',{manual:x.source==='manual'}):'';return `<div class="inventory-art ${large?'is-large':''}">${image||icon(groups.find(g=>g[0]===x.category)?.[2]||'inventory')}</div>`;}
 const button=(label,attr,body=label,cls='')=>`<button type="button" ${attr} class="${cls}" aria-label="${esc(label)}" title="${esc(label)}">${body}</button>`;
 function quick(x){if(!canEdit)return '';if(x.source==='manual')return button('Редактировать','data-inv-edit="'+x.index+'"',icon('edit'));if(V().isConsumable(x.item))return `<button type="button" data-v2-consume="${esc(x.id)}" ${!x.quantity?'disabled':''} title="Использовать 1 шт." aria-label="Использовать 1 шт.">▷</button>`;const target=V().stateFor(x.item);if(!target||target==='inventory'||!x.quantity)return '';return button(x.active?'Убрать в инвентарь':({equipped:'Экипировать',installed:'Установить',loaded:'Загрузить',learned:'Изучить'}[target]||labels[target]),`data-inv-toggle="${esc(x.id)}"`,x.active?'↙':'↗');}
 function row(x){const selected=state().selected===x.id;return `<article class="inventory-row sheet-surface-structural ${selected?'is-selected':''} ${x.location==='consumed'?'is-consumed':''}"><button class="inventory-select" data-inv-select="${esc(x.id)}" aria-expanded="${selected}" aria-label="Подробности: ${esc(x.name)}">${art(x)}<span class="inventory-row-copy"><strong>${esc(x.name||'Без названия')}</strong><small>${esc(x.source==='catalog'?className(x.item):'Прочее')} · ${x.source==='catalog'?'Справочник':'Ручной'}</small><span class="inventory-state ${x.active?'is-active':''}">${esc(labels[x.location])} <b>×${x.quantity}</b></span></span><span class="inventory-row-description">${x.source==='catalog'?S().parameters(x.item):''}<span>${esc(x.description)}</span>${x.item.archived?'<small>Архив · сохранённый экземпляр</small>':''}</span></button><div class="inventory-row-actions">${quick(x)}<details class="inventory-menu"><summary aria-label="Дополнительные действия" title="Дополнительные действия">•••</summary><div>${button('Подробнее',`data-inv-select="${esc(x.id)}"`)}${canEdit?(x.source==='manual'?button('Редактировать',`data-inv-edit="${x.index}"`)+button('Удалить',`data-inv-remove="${x.index}"`):button('Убрать из владения',`data-v2-remove="${esc(x.id)}"`)):''}</div></details></div></article>`;}
 function effects(item){const names={while_equipped:'при экипировке',while_installed:'при установке',always:'постоянно',while_loaded:'при загрузке',while_learned:'после изучения'};return (item.effects||[]).map(e=>{const ids=e.targetType==='attribute'?V().attributeIds:V().skillIds;const index=ids.indexOf(e.targetId);const target=index<0?({armor:'Броня',max_hp:'Здоровье'}[e.targetId]||e.targetId||''):D[e.targetType==='attribute'?'attributes':'skills'][index].name;const condition=e.type==='conditional_modifier';const details=e.conditions?Object.entries(e.conditions).map(([k,v])=>({skillId:'Навык',distanceMin:'Дистанция от',distanceMax:'Дистанция до',ownWeapon:'Собственное оружие'}[k]||k)+': '+v).join(' · '):'';return `<div class="inventory-effect"><b>${esc(e.value==null?'':S().sign(e.value))} ${esc(target)}</b><span>${esc(e.description||e.text||names[e.duration]||e.duration||'По описанию предмета')}</span>${condition?'<small>Условный бонус · '+esc(details)+'</small>':''}${['temporary_effect','rules_only'].includes(e.type)?'<small>Применяется по правилам, без автоматического изменения базы</small>':''}</div>`;}).join('');}
 function facts(item){const fields=typeof catalogFields==='undefined'?[]:(catalogFields[item.classId]||[]);const facts=[['Производитель',item.manufacturer],['Подтип',item.subtype],['Базовая стоимость',item.economy?.price==null?'':item.economy.price+(item.classId==='perk'?' ОО':' эдди')],...fields.map(([key,label,type])=>[label,['equipment','equipmentText','activation'].includes(type)?item.equipment?.[key]:item.stats?.[key]??item[key]]),['Ограничения',item.availability?.restrictions]];return '<dl class="inventory-facts">'+facts.filter(([,v])=>v!==null&&v!==undefined&&v!=='').map(([label,v])=>'<div><dt>'+esc(label)+'</dt><dd>'+esc(typeof v==='boolean'?(v?'Да':'Нет'):({passive:'Пассивный',active:'Активный'}[v]||v))+'</dd></div>').join('')+'</dl>';}
 function detail(x){return `<div class="inventory-detail-content">${art(x,true)}${x.source==='catalog'?S().detail(x.instance).replace('<details class="v2-item-rules">','<details class="v2-item-rules" open>')+facts(x.item)+effects(x.item):`<h2>${esc(x.name)}</h2><p class="inventory-state">Ручной · ${x.quantity} шт.</p><p class="inventory-full-description">${esc(x.description||'Без описания')}</p>${canEdit?`<div class="inventory-detail-actions">${button('Редактировать',`data-inv-edit="${x.index}"`,icon('edit')+' Редактировать')}${button('Удалить',`data-inv-remove="${x.index}"`,'Удалить','danger')}</div>`:''}`}</div>`;}
 function renderInventory(){const rows=entries(),s=state(),filtered=query(rows,s),selected=rows.find(x=>x.id===s.selected);if(!selected)s.selected=null;const stats=[['Эдди','inventory',`<input type="number" min="0" step="1" data-path="money" aria-label="Баланс эдди" value="${card.money}" ${canEdit?'':'disabled'}>`],['Всего предметов','inventory',rows.length],['Из справочника','notes',rows.filter(x=>x.source==='catalog').length],['Ручные','edit',card.inventory.length],['Экипировано','armor',rows.filter(x=>x.active).length]];const options=groups.map(g=>`<option value="${g[0]}" ${s.category===g[0]?'selected':''}>${g[1]} · ${g[0]==='all'?rows.length:rows.filter(x=>x.category===g[0]).length}</option>`).join('');return `<div class="inventory-v3"><div class="inventory-top"><div class="inventory-summary">${stats.map(([label,i,val])=>`<div class="inventory-stat sheet-surface-technical"><span>${icon(i)}${label}</span><strong>${val}</strong></div>`).join('')}</div>${canEdit?`<div class="inventory-add-actions">${button('Добавить предмет','id="inventory-add-manual"','+ Добавить предмет','yellow')}${button('Из справочника','data-v2-add="all"',icon('notes')+' Из справочника')}</div>`:''}</div><div class="inventory-tools"><label class="inventory-search"><span class="dossier-visually-hidden">Поиск по названию, описанию и производителю</span><input id="inventory-search" type="search" placeholder="Поиск по названию и описанию" value="${esc(s.query)}"></label><div class="inventory-filters" aria-label="Источник и состояние">${[['all','Все'],['catalog','Справочник'],['manual','Ручные']].map(([id,label])=>button(label,`data-inv-source="${id}" aria-pressed="${s.source===id}"`)).join('')}${button('Экипировано',`id="inventory-active" aria-pressed="${s.active}"`,icon('armor')+' Экипировано')}</div><label class="inventory-sort">Сортировка<select id="inventory-sort">${[['default','По умолчанию'],['alphabet','По алфавиту'],['category','По категории'],['quantity','По количеству'],['price','По стоимости'],['equipped','Сначала экипированные']].map(([id,label])=>`<option value="${id}" ${s.sort===id?'selected':''}>${label}</option>`).join('')}</select></label><label class="inventory-mobile-category">Категория<select id="inventory-category">${options}</select></label></div><div class="inventory-workspace ${selected?'has-detail':''}"><aside class="inventory-categories sheet-surface-base" aria-label="Категории предметов">${groups.filter(g=>g[0]==='all'||g[0]===s.category||rows.some(x=>x.category===g[0])).map(g=>button(g[1],`data-inv-category="${g[0]}" aria-pressed="${s.category===g[0]}"`,icon(g[2])+`<span>${g[1]}</span><b>${g[0]==='all'?rows.length:rows.filter(x=>x.category===g[0]).length}</b>`)).join('')}</aside><div class="inventory-list" aria-label="Предметы">${filtered.map(row).join('')||`<div class="inventory-empty sheet-surface-base">${icon('inventory')}<h2>${rows.length?'Ничего не найдено':'Инвентарь пуст'}</h2><p>${rows.length?'Попробуй изменить поиск или фильтры':'Добавь предмет или выбери снаряжение из справочника'}</p></div>`}</div>${selected?`<aside class="inventory-detail sheet-surface-base" aria-label="Подробности предмета"><header><span>Сведения о предмете</span>${button('Закрыть подробности','id="inventory-close-detail"','×')}</header>${detail(selected)}</aside>`:''}</div></div>`;}
 function saveManual(index,values){if(!canEdit)throw Error('Карточка доступна только для просмотра');if(!values.name.trim())throw Error('Введи название предмета');if(!Number.isSafeInteger(values.quantity)||values.quantity<1)throw Error('Количество должно быть целым числом от 1');const next=E.clone(card);if(index==null){if(next.inventory.length>=500)throw Error('Слишком много записей');next.inventory.push({...values,name:values.name.trim()});state().selected='manual:'+(next.inventory.length-1);}else {if(!next.inventory[index])throw Error('Предмет не найден');next.inventory[index]={...next.inventory[index],...values,name:values.name.trim()};}card=E.validate(next,D);changed();render();}
 function manualDialog(index=null){if(!canEdit)return;const x=index==null?{name:'',description:'',quantity:1}:card.inventory[index];if(!x)return;modal(index==null?'Добавить предмет':'Редактировать предмет',`<form id="inventory-manual-form" class="inventory-form"><label class="field"><span>Название</span><input id="inventory-manual-name" maxlength="20000" required value="${esc(x.name)}"></label><label class="field"><span>Количество</span><input id="inventory-manual-quantity" type="number" min="1" step="1" required value="${x.quantity??1}"></label><label class="field"><span>Описание</span><textarea id="inventory-manual-description" maxlength="20000">${esc(x.description)}</textarea></label><div class="inventory-detail-actions"><button class="yellow">Сохранить</button><button type="button" id="inventory-cancel">Отмена</button></div></form>`);$('#inventory-cancel').onclick=closeModal;$('#inventory-manual-form').onsubmit=e=>{e.preventDefault();try{saveManual(index,{name:$('#inventory-manual-name').value,description:$('#inventory-manual-description').value,quantity:Number($('#inventory-manual-quantity').value)});closeModal();}catch(e){error(e);}};$('#inventory-manual-name').focus();}
 function removeManual(index){if(!canEdit)return;const x=card.inventory[index];if(!x)return;modal('Удалить ручной предмет?',`<p>${esc(x.name)}</p><button id="inventory-confirm-remove" class="danger">Удалить предмет</button>`);$('#inventory-confirm-remove').onclick=()=>{if(!canEdit)return;const next=E.clone(card);next.inventory.splice(index,1);state().selected=null;card=E.validate(next,D);changed();render();closeModal();};}
 function select(id){state().selected=id;render();if(window.matchMedia('(max-width: 899px)').matches){const x=entries().find(x=>x.id===id);if(!x)return;showDetail(x);}}
 function showDetail(x){modal('Сведения о предмете','<div data-inventory-modal>'+detail(x)+'</div>');bind();S().bind();}
 function refreshDetail(){if(!$('#dialog').open||!$('#dialog').querySelector('[data-inventory-modal]'))return;const x=entries().find(x=>x.id===state().selected);if(x)showDetail(x);else closeModal();}
 function catalogDialog(category='all'){if(!canEdit)return;const all=V().all(D.catalog).filter(i=>!i.archived&&i.classId&&!['worm','heavy_demon'].includes(i.classId)&&(category==='all'||V().classes.find(c=>c.id===i.classId)?.category===category));let chosen=null;modal('Из справочника',`<div class="inventory-catalog"><p class="hint">Добавление не списывает эдди или опыт. Активация и изучение — отдельные действия.</p><label class="field"><span>Поиск</span><input id="inventory-catalog-search" type="search" placeholder="Название, описание, производитель"></label><label class="field"><span>Категория</span><select id="inventory-catalog-category">${groups.filter(g=>g[0]==='all'||all.some(i=>group(i)===g[0])).map(g=>`<option value="${g[0]}">${g[1]}</option>`).join('')}</select></label><div id="inventory-catalog-results" class="inventory-catalog-results"></div><form id="inventory-catalog-form"><label class="field"><span>Количество</span><input id="inventory-catalog-quantity" type="number" min="1" max="999" step="1" required value="1"></label><button id="inventory-catalog-submit" class="yellow" disabled>Добавить в инвентарь</button></form></div>`);const fill=()=>{const q=$('#inventory-catalog-search').value.toLocaleLowerCase('ru'),cat=$('#inventory-catalog-category').value;const rows=all.filter(i=>(cat==='all'||group(i)===cat)&&(name(i)+' '+(i.description||'')+' '+(i.manufacturer||'')).toLocaleLowerCase('ru').includes(q));$('#inventory-catalog-results').innerHTML=rows.map(i=>`<button type="button" data-inv-catalog="${esc(i.catalogId)}" aria-pressed="${chosen===i.catalogId}">${art({source:'catalog',category:group(i),item:i})}<span><strong>${esc(name(i))}</strong><small>${esc(className(i))}</small>${S().parameters(i)}</span></button>`).join('')||'<p class="hint">Подходящих предметов нет</p>';document.querySelectorAll('[data-inv-catalog]').forEach(b=>b.onclick=()=>{chosen=b.dataset.invCatalog;$('#inventory-catalog-submit').disabled=false;fill();});};$('#inventory-catalog-search').oninput=fill;$('#inventory-catalog-category').onchange=fill;fill();$('#inventory-catalog-form').onsubmit=e=>{e.preventDefault();if(!canEdit||!chosen)return;try{const next=V().addEquipment(card,D.catalog,chosen,Number($('#inventory-catalog-quantity').value));state().selected=next.equipmentItems.at(-1).instanceId;S().commit(next);closeModal();notify('Предмет добавлен в инвентарь');}catch(e){error(e);}};}
 function bind(){document.querySelectorAll('[data-inv-select]').forEach(b=>b.onclick=()=>select(b.dataset.invSelect));document.querySelectorAll('[data-inv-category]').forEach(b=>b.onclick=()=>{state().category=b.dataset.invCategory;render();});document.querySelectorAll('[data-inv-source]').forEach(b=>b.onclick=()=>{state().source=b.dataset.invSource;render();});document.querySelectorAll('[data-inv-edit]').forEach(b=>b.onclick=()=>manualDialog(Number(b.dataset.invEdit)));document.querySelectorAll('[data-inv-remove]').forEach(b=>b.onclick=()=>removeManual(Number(b.dataset.invRemove)));document.querySelectorAll('[data-inv-toggle]').forEach(b=>b.onclick=()=>{if(!canEdit)return;const x=entries().find(x=>x.id===b.dataset.invToggle);try{if(x.item.classId==='perk'&&!x.active&&!x.instance?.metadata?.learned){window.ND_PROGRESSION?.open(x.item.catalogId);return;}S().commit(V().setEquipmentState(card,D.catalog,x.id,x.active?'inventory':V().stateFor(x.item)));}catch(e){notify(e.message);}});const search=$('#inventory-search');if(search)search.oninput=()=>{const pos=search.selectionStart;state().query=search.value;render();const next=$('#inventory-search');next.focus();if(next.setSelectionRange)next.setSelectionRange(pos,pos);};if($('#inventory-sort'))$('#inventory-sort').onchange=e=>{state().sort=e.target.value;render();};if($('#inventory-category'))$('#inventory-category').onchange=e=>{state().category=e.target.value;render();};if($('#inventory-active'))$('#inventory-active').onclick=()=>{state().active=!state().active;render();};if($('#inventory-add-manual'))$('#inventory-add-manual').onclick=()=>manualDialog();if($('#inventory-close-detail'))$('#inventory-close-detail').onclick=()=>{state().selected=null;render();};}
 return {render:renderInventory,bind,refreshDetail,catalogDialog,entries,query,saveManual,state};
})();
